import React from 'react';
import { Layout, Avatar } from 'antd';
import Chat from './components/Chat';

const { Header, Content } = Layout;

function App() {
  return (
    <Layout style={{ minHeight: '100vh', background: '#fafbfc' }}>
      <Header style={{ background: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'space-between', boxShadow: '0 2px 8px #f0f1f2' }}>
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <img src="https://uploads-ssl.webflow.com/5e5e1c2e6e6b6c1b1c8b4567/5e5e1c2e6e6b6c2b1c8b4568_logo-cortex.svg" alt="cortex logo" style={{ height: 32, marginRight: 12 }} />
          <span style={{ fontWeight: 700, fontSize: 24, color: '#222' }}>cortex</span>
        </div>
        <Avatar style={{ background: '#e6e6e6', color: '#888' }}>WM</Avatar>
      </Header>
      <Content style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 'calc(100vh - 64px)' }}>
        <Chat />
      </Content>
    </Layout>
  );
}

export default App;
